    "approved_review_count": {
      "expression": "COUNT(*)"
    },
    "assigned_pull_request_count": {
      "expression": "COUNT(DISTINCT pull_request_assignees.pull_request_id)",
      "type": "BIGINT"
    },
    "authored_commit_comment_active_days": {
      "expression": "COUNT(DISTINCT authored_commit_comments.authored_commit_comment_created_day)"
    },
    "authored_commit_comment_count": {
      "expression": "COUNT(*)"
    },
    "authored_commit_comment_repository_count": {
      "expression": "COUNT(DISTINCT authored_commit_comments.repository_node_id)"
    },
    "authored_discussion_active_days": {
      "expression": "COUNT(DISTINCT authored_discussions.authored_discussion_created_day)"
    },
    "authored_discussion_comment_active_days": {
      "expression": "COUNT(DISTINCT authored_discussion_comments.authored_discussion_comment_created_day)"
    },
    "authored_discussion_comment_count": {
      "expression": "COUNT(*)"
    },
    "authored_discussion_comment_repository_count": {
      "expression": "COUNT(DISTINCT authored_discussion_comments.repository_node_id)"
    },
    "authored_discussion_comment_unknown_repository_count": {
      "expression": "COUNT(*)"
    },
    "authored_discussion_count": {
      "expression": "COUNT(*)"
    },
    "authored_discussion_repository_count": {
      "expression": "COUNT(DISTINCT authored_discussions.repository_node_id)"
    },
    "authored_issue_active_days": {
      "expression": "COUNT(DISTINCT authored_issues.authored_issue_created_day)"
    },
    "authored_issue_comment_active_days": {
      "expression": "COUNT(DISTINCT authored_issue_comments.authored_issue_comment_created_day)"
    },
    "authored_issue_comment_count": {
      "expression": "COUNT(*)"
    },
    "authored_issue_comment_repository_count": {
      "expression": "COUNT(DISTINCT authored_issue_comments.repository_node_id)"
    },
    "authored_issue_count": {
      "expression": "COUNT(*)"
    },
    "authored_issue_repository_count": {
      "expression": "COUNT(DISTINCT authored_issues.repository_node_id)"
    },
    "authored_median_merge_hours": {
      "expression": "MEDIAN(authored_pull_requests.merge_hours)"
    },
    "authored_merged_pr_count": {
      "expression": "COUNT(*)"
    },
    "authored_pr_active_days": {
      "expression": "COUNT(DISTINCT authored_pull_requests.authored_pr_created_day)"
    },
    "authored_pr_count": {
      "expression": "COUNT(*)"
    },
    "authored_pr_repository_count": {
      "expression": "COUNT(DISTINCT authored_pull_requests.repository_node_id)"
    },
    "label_count": {
      "expression": "COUNT(*)"
    },
    "labeled_pull_request_count": {
      "expression": "COUNT(DISTINCT pull_request_labels.pull_request_id)",
      "type": "BIGINT"
    },
    "latest_approved_reviewer_count": {
      "expression": "COUNT(*) FILTER (WHERE latest_reviewer_reviews.state = 'APPROVED')"
    },
    "latest_reviewer_review_count": {
      "expression": "COUNT(*)"
    },
    "mean_first_review_hours": {
      "expression": "AVG(first_review_prs.first_review_hours)"
    },
    "median_first_review_hours": {
      "expression": "MEDIAN(first_review_prs.first_review_hours)"
    },
    "median_merge_hours": {
      "expression": "MEDIAN(pull_requests.merge_hours)"
    },
    "merged_prs": {
      "expression": "COUNT(*)"
    },
    "monthly_authored_pr_total": {
      "expression": "SUM(authored_pr_count) OVER (PARTITION BY authored_pull_requests.user_id, authored_pull_requests.user_login, authored_pull_requests.authored_pr_created_month)"
    },
    "monthly_repository_pr_share": {
      "expression": "authored_pr_count / NULLIF(monthly_authored_pr_total, 0)"
    },
    "monthly_user_pr_rank": {
      "expression": "DENSE_RANK() OVER (PARTITION BY authored_pull_requests.authored_pr_created_month ORDER BY authored_pr_count DESC)"
    },
    "organization_count": {
      "expression": "COUNT(*)"
    },
    "organization_member_count": {
      "expression": "COUNT(*)"
    },
    "p90_first_review_hours": {
