  "name": "github",
  "policy": {
    "allow_semantic_joins": true,
    "dataset_semantics": {
      "authored_commit_comments": {
        "comment": "Commit comments authored by the selected user, not commits or code-change counts.",
        "key_evidence": "declared"
      },
      "authored_discussion_comments": {
        "comment": "Discussion comments and replies authored by the selected user. Missing discussion/repository context remains NULL and does not discard an attributable comment.",
        "key_evidence": "declared"
      },
      "authored_discussions": {
        "comment": "Repository discussions started by the selected user across visible repositories.",
        "key_evidence": "declared"
      },
      "authored_issue_comments": {
        "comment": "Issue and PR timeline comments authored by the selected user; these are comment records, not review submissions or distinct issues.",
        "key_evidence": "declared"
      },
      "authored_issues": {
        "comment": "Issues authored by the selected user across visible repositories. Creation activity; current status is not status at a historical period end.",
        "key_evidence": "declared"
      },
      "authored_pull_requests": {
